import { createCurrentMasterFulfilment, CURRENT_PHYSICAL_DISPATCH_ENABLED } from 'backend/r2stockCurrentFulfilment.js';
import { createCurrentWarehouseReceiptRouter, createCurrentWarehouseOrdersRouter } from 'backend/r2stockCurrentCommands.js';
import { operationId } from 'backend/r2purchaseOperationJournal.js';
import { PURCHASE_COLLECTIONS } from 'backend/r2purchaseProjection.js';
import { webMethod, Permissions } from 'wix-web-module';
import { currentMember } from 'wix-members-backend';
import { fulfilmentStore, readCustomerFulfilment, saveCustomerFulfilment } from 'backend/r2customerFulfilmentService.js';
async function staffContext(){const member=await currentMember.getMember({fieldsets:['FULL']});if(!member?._id||member.status!=='APPROVED')throw Error('Sign in with an approved Master staff account.');const rows=(await fulfilmentStore.all('StaffMasterAccess')).filter(row=>String(row.staffEmail||'').trim().toLowerCase()===String(member.loginEmail||'').trim().toLowerCase());const row=rows.length===1?rows[0]:null;if(!row||row.description!==member._id||String(row.staffStatus).toUpperCase()!=='ACTIVE'||!row.title||!row.staffName)throw Error('Master staff access is not configured.');const role=String(row.role).toUpperCase(),departments=(row.departments||[]).map(value=>String(value).toUpperCase()),admin=role==='SUPER ADMIN',support=departments.includes('SUPPORT'),warehouse=departments.includes('WAREHOUSE'),account=departments.includes('ACCOUNT');if(!admin&&!support&&!warehouse&&!account)throw Error('Fulfilment access is not authorized.');return {memberId:member._id,staffId:row.title,staffName:row.staffName,role,readFinancial:admin||support||account,canSelectShipment:false,canInvoiceShipment:admin||support,canDispatchShipment:admin||warehouse};}
async function currentMasterFulfilment(company,staff){return createCurrentMasterFulfilment({company,authenticateOriginalWarehouse:async()=>{
 const current=await staffContext();if(JSON.stringify(current)!==JSON.stringify(staff))throw Error('Master fulfilment identity changed. Retain original request.');return current;
}});}
export const getCustomerFulfilment=webMethod(Permissions.SiteMember,async(company,resume)=>{const staff=await staffContext();
 if(resume!==undefined){if(!['NCT','GHR'].includes(company)||resume?.resume!=='WAREHOUSE_DISPATCH_V1'||Object.keys(resume).length!==1||staff.canDispatchShipment!==true)throw Error('Original dispatch recovery identity required');return {ok:true,company,schema:'WAREHOUSE_DISPATCH_RESUME_V1',staff:{staffId:staff.staffId,memberId:staff.memberId,staffName:staff.staffName}};}
 const result=await createCurrentWarehouseOrdersRouter({company,readControl:()=>fulfilmentStore.read(PURCHASE_COLLECTIONS[company].activity,operationId(company,'STOCK_CONTROL')),
 readCurrent:async()=> (await currentMasterFulfilment(company,staff)).read(company),readLegacy:()=>readCustomerFulfilment(company,staff)})();if(!staff.readFinancial){result.debtorInvoices=[];delete result.customerAccount;delete result.accountVersion;result.lines=result.lines.map(({sellingPriceCtn,...row})=>row);result.shipments=result.shipments.map(row=>({...row,invoice:row.invoice?{number:row.invoice.number,date:row.invoice.date}:undefined,lines:row.lines.map(({sellingPriceCtn,...line})=>line)}));}return {...result,permissions:{invoice:staff.canInvoiceShipment&&result.stockCurrent?.stockProtocol!==1,dispatch:staff.canDispatchShipment&&(result.stockCurrent?.stockProtocol!==1||CURRENT_PHYSICAL_DISPATCH_ENABLED===true)}};});
export const saveCustomerShipment=webMethod(Permissions.SiteMember,async(company,requestId,input,stockCurrent)=>{const staff=await staffContext();try{return await createCurrentWarehouseReceiptRouter({company,
 readControl:()=>fulfilmentStore.read(PURCHASE_COLLECTIONS[company].activity,operationId(company,'STOCK_CONTROL')),
 saveCurrent:async(selected,request)=>(await currentMasterFulfilment(selected,staff)).save(request),saveLegacy:()=>saveCustomerFulfilment({company,staff,requestId,input})})({requestId,input,stockCurrent});}catch(error){return {ok:false,requestId,error:String(error?.message||'Shipment save could not be confirmed.')};}});
